import{_ as r,o as t,c as a,a0 as o}from"./chunks/framework.BmibOe8h.js";const _=JSON.parse('{"title":"关于我","description":"内核折腾，向死而生。","frontmatter":{"title":"关于我","date":"2026-08-01T00:00:00.000Z","description":"内核折腾，向死而生。"},"headers":[],"relativePath":"blog/2026-08-01-guan-yu-wo.md","filePath":"blog/2026-08-01-guan-yu-wo.md","lastUpdated":1785699240000}'),s={name:"blog/2026-08-01-guan-yu-wo.md"};function n(p,e,l,i,g,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<p>不是开发者，就是个折腾的。</p><p>设备真我 GT5 Pro，骁龙 8 Gen 3。日常在这台机器上刷内核、改配置、反复 bootloop。</p><h2 id="内核" tabindex="-1">内核 <a class="header-anchor" href="#内核" aria-label="Permalink to &quot;内核&quot;">​</a></h2><p><a href="https://github.com/Lxyao077/oppo_oplus_realme_sm8650" target="_blank" rel="noreferrer">oppo_oplus_realme_sm8650</a> 是我维护最久的仓库。从 cctv18 fork 出来之后，把构建流水线从 6.1.57 拉到 6.1.141，七套 fastbuild workflow，支持 ReSukiSU、SUSFS、KPM、Droidspaces、BBR 可选项。改 YAML 比改内核代码多——那个 @cctv18 的标记改了好几轮才清干净。</p><p><a href="https://github.com/Lxyao077/GKI_KernelSU_SUSFS" target="_blank" rel="noreferrer">GKI_KernelSU_SUSFS</a> 覆盖 5.10 到 6.12，一套 CI 出所有版本。内置 ReSukiSU + SUSFS，BBG 基带守护、Droidspaces 容器、Re-Kernel 等作为可选项。做这个的动机很简单：不想每换一个内核版本就重新配一遍。</p><h2 id="项目" tabindex="-1">项目 <a class="header-anchor" href="#项目" aria-label="Permalink to &quot;项目&quot;">​</a></h2><p>基本都是 fork，在巨人肩膀上修修补补。</p><p><strong><a href="https://github.com/Lxyao077/vector-fork" target="_blank" rel="noreferrer">Vector Fork</a></strong> — LSPosed 的复苏分支。改过 daemon/app 架构、AIDL 接口层、CI 签名逻辑。LSPosed 停更之后这条线是少数还能在 Android 14/15 上跑起来的。</p><p><strong><a href="https://github.com/Lxyao077/TieJia" target="_blank" rel="noreferrer">TieJia</a></strong> — Play Integrity 强过检。TEESimulator + PIF 组合，目标是解锁设备过 Strong Integrity。</p><p><strong><a href="https://github.com/Lxyao077/specter" target="_blank" rel="noreferrer">Specter</a></strong> — 统一 PI + root 隐藏方案。冲突检测、Zygisk 自动识别、hotinstall 免重启更新，这几个设计点值得拆开看。</p><p><strong><a href="https://github.com/Lxyao077/ReZygisk" target="_blank" rel="noreferrer">ReZygisk</a> / <a href="https://github.com/Lxyao077/YukiZygisk" target="_blank" rel="noreferrer">YukiZygisk</a></strong> — 内核级 Zygisk 注入，比传统 ptrace 干净。</p><p><strong><a href="https://github.com/Lxyao077/YukiSU" target="_blank" rel="noreferrer">YukiSU</a></strong> — 在 KSU/APatch 之外找更灵活的内核 hook 路径。</p><p><strong><a href="https://github.com/Lxyao077/susfs4ksu-module" target="_blank" rel="noreferrer">susfs4ksu-module</a></strong> — SUSFS 内核态文件系统挂载隐藏的用户态控制层。</p><p><strong><a href="https://github.com/Lxyao077/LSPosed-Irena" target="_blank" rel="noreferrer">LSPosed-Irena</a></strong> — 又一个 LSPosed fork。命名自嘲 &quot;useless&quot;，但社区里每个能跑的 LSPosed 分支都是宝贝。</p><p><strong><a href="https://github.com/Lxyao077/ksu_toolkit" target="_blank" rel="noreferrer">ksu_toolkit</a></strong> — 日常排查模块冲突、验证签名。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>上面这些东西，大部分是站在别人肩膀上修修改改，算不上开发。但每一次 debug 一个 CI 报错、改一行 defconfig、绕过一次检测，都是真实踩过的坑。</p><p>如果这些对你有用，欢迎 Star，有问题直接提 Issue。</p><p>GitHub: <a href="https://github.com/Lxyao077" target="_blank" rel="noreferrer">@Lxyao</a></p>',19)])])}const c=r(s,[["render",n]]);export{_ as __pageData,c as default};
